export const settingsJavascript = `export default function mount(element,host){let active=true;const input=document.createElement('input');input.name='preference';input.setAttribute('aria-label','偏好');element.append(input);host.call('read').then(value=>{if(active)input.value=value.value;}).catch(error=>host.toast(String(error)));const save=document.createElement('button');save.textContent='保存应用偏好';save.onclick=()=>host.call('save',{value:input.value}).then(()=>host.navigate('/saved')).catch(error=>host.toast(String(error)));element.append(save);return()=>{active=false;element.replaceChildren();};}`;
